terraform {
  required_providers {
    datadog = {
      source  = "DataDog/datadog"
      version = ">= 3.30.0"
    }
  }
}

# --- Automated Log Exclusion Filter for transactions-prod ---
resource "datadog_logs_index" "log_filter_transactions_prod" {
  name           = "transactions-prod"
  filter {
    query = "*"
  }
  exclusion_filter {
    name    = "winnow_drop_unqueried_debug_logs"
    is_enabled = true
    filter {
      query = "status:debug OR source:(trace-dump OR healthcheck)"
      sample_rate = 0.05 # Retain only 5% of debug noise
    }
  }
}

